//! 🗜️ Complete Deflate semantic owners retain original paid projection, reconstruction and borrowed validation.
use super::{DeflateSnapshot,DeflateLevelHint};
use semio_framework_os_kernel::{io::control::{NativeSnapshotBodyWallet,NativeSnapshotDecodeOwner,NativeSnapshotEncodeOwner},sqlite_snapshot::{SqliteDatabase,SqliteTable,SqliteValue,SqliteSnapshotControl,SqliteSnapshotReceivingControl,SqliteSnapshotPhase,artifact::receiving::{Port,Direction,Projection,Scalar,row,cell,text_cell,push_row,sort,integer,ordinal,validate_schema_sql,check_database,settle}}};
use semio_framework_value::{ValueError,ValueRefusalKind};
use std::{cell::{Cell,RefCell},mem::size_of};
pub type Result<T>=std::result::Result<T,ValueError>;
type Paid<'a,'b,'c>=Port<'a,'b,'c,NativeSnapshotBodyWallet>;
const SQL:&str=include_str!("../🗄️.sql");
const TABLES:[(&str,usize);2]=[("deflate_document",6),("deflate_payload_byte",4)];
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,"Deflate complete semantic state differs")}
fn add(a:usize,b:usize)->Result<usize>{a.checked_add(b).ok_or_else(||ValueError::literal(ValueRefusalKind::WorkLimit,"Deflate semantic extent overflow"))}
fn empty()->DeflateSnapshot{DeflateSnapshot{schema:String::new(),compression_method:0,window_bits:0,compression_level_hint:DeflateLevelHint::Fastest,dict_id:None,payload:Vec::new()}}
#[derive(semio_framework_value::RetireOwned)]
struct Frame{projection:Projection,snapshot:DeflateSnapshot,ids:Vec<usize>,ordered:Vec<usize>,status:Option<Result<()>>}
impl Frame{fn new()->Self{Self{projection:Projection::new(),snapshot:empty(),ids:Vec::new(),ordered:Vec::new(),status:None}}}
pub fn definition(index:usize)->&'static str{SQL.split(';').map(str::trim).filter(|text|!text.is_empty()).nth(index).unwrap()}
fn table(database:&SqliteDatabase,index:usize)->Result<&SqliteTable>{database.tables.iter().find(|table|table.name.eq_ignore_ascii_case(TABLES[index].0)).ok_or_else(invalid)}
fn bounded(row:&semio_framework_os_kernel::sqlite_snapshot::SqliteRow,column:usize,maximum:i64)->Result<i64>{let value=integer(row,column)?;if !(0..=maximum).contains(&value){return Err(invalid())}Ok(value)}
fn equal(left:&str,right:&str,port:&mut Paid<'_,'_,'_>)->Result<()>{port.work(2,0)?;if left.len()!=right.len(){return Err(invalid())}let total=left.len();port.control.checkpoint(port.phase(),0,total)?;for(index,(left,right))in left.as_bytes().chunks(256).zip(right.as_bytes().chunks(256)).enumerate(){port.work(2,0)?;if left!=right{return Err(invalid())}port.control.checkpoint(port.phase(),index*256+left.len(),total)?}Ok(())}
fn project(source:&DeflateSnapshot,frame:&mut Frame,port:&mut Paid<'_,'_,'_>)->Result<()>{
 port.work(1,0)?;if source.compression_method>15||source.window_bits>15{return Err(invalid())}let total=add(source.payload.len(),1)?;port.control.check_rows(total)?;let limits=port.control.limits();let schema=TABLES.iter().enumerate().try_fold(0usize,|sum,(index,(name,_))|add(sum,add(name.len(),definition(index).len())?))?;if limits.max_tables<2||limits.max_columns<6||SQL.len()>limits.max_schema_bytes||schema>limits.max_schema_bytes{return Err(ValueError::literal(ValueRefusalKind::WorkLimit,"Deflate authored schema exceeds original allowance"))}
 let output=&mut frame.projection;port.vector(2,&mut output.database.tables,1)?;for(index,(name,_))in TABLES.iter().enumerate(){port.work(2,size_of::<SqliteTable>())?;output.database.tables.push(SqliteTable{name:String::new(),sql:String::new(),rows:Vec::new()});let table=&mut output.database.tables[index];port.text(name,&mut table.name,2)?;port.text(definition(index),&mut table.sql,2)?;port.vector(if index==0{1}else{source.payload.len()},&mut table.rows,2)?;}
 row(output,1,6,port)?;text_cell(output,&source.schema,port)?;for value in [source.compression_method,source.window_bits,source.compression_level_hint.to_bits()]{cell(output,Scalar::Integer(i64::from(value)),port)?}cell(output,source.dict_id.map(|value|Scalar::Integer(i64::from(value))).unwrap_or(Scalar::Null),port)?;push_row(output,0,port)?;
 for(index,value)in source.payload.iter().enumerate(){row(output,ordinal(add(index,1)?)?,4,port)?;cell(output,Scalar::Integer(1),port)?;cell(output,Scalar::Integer(ordinal(index)?),port)?;cell(output,Scalar::Integer(i64::from(*value)),port)?;push_row(output,1,port)?;if(index+1)%256==0{port.control.checkpoint(port.phase(),index+1,source.payload.len())?}}port.control.checkpoint(port.phase(),total,total)
}
fn read(database:&SqliteDatabase,frame:&mut Frame,source:Option<&DeflateSnapshot>,port:&mut Paid<'_,'_,'_>)->Result<()>{
 validate_schema_sql(database,SQL,port)?;check_database(database,port)?;let documents=&table(database,0)?.rows;if documents.len()!=1{return Err(invalid())}let document=&documents[0];port.work(2,0)?;if document.rowid!=1||document.values.len()!=6||integer(document,0)?!=1{return Err(invalid())}let schema=match &document.values[1]{SqliteValue::Text(value)=>value.as_str(),_=>return Err(invalid())};let method=bounded(document,2,15)?as u8;let window=bounded(document,3,15)?as u8;let hint=bounded(document,4,3)?as u8;let dictionary=match document.values[5]{SqliteValue::Null=>None,SqliteValue::Integer(value)=>Some(u32::try_from(value).map_err(|_|invalid())?),_=>return Err(invalid())};
 let rows=&table(database,1)?.rows;port.vector(rows.len(),&mut frame.ids,2)?;port.vector(rows.len(),&mut frame.ordered,2)?;for(index,row)in rows.iter().enumerate(){port.work(2,2*size_of::<usize>())?;if row.values.len()!=4||integer(row,0)?!=row.rowid||integer(row,1)?!=1{return Err(invalid())}frame.ids.push(index);frame.ordered.push(index);}sort(&mut frame.ids,port,|a,b|Ok(rows[a].rowid.cmp(&rows[b].rowid)))?;for pair in frame.ids.windows(2){port.work(2,0)?;if rows[pair[0]].rowid==rows[pair[1]].rowid{return Err(invalid())}}sort(&mut frame.ordered,port,|a,b|Ok(integer(&rows[a],2)?.cmp(&integer(&rows[b],2)?)))?;
 if let Some(source)=source{if (method,window,hint,dictionary,rows.len())!=(source.compression_method,source.window_bits,source.compression_level_hint.to_bits(),source.dict_id,source.payload.len()){return Err(invalid())}equal(&source.schema,schema,port)?}else{port.control.admit_reconstruction_bytes(schema.len())?;port.text(schema,&mut frame.snapshot.schema,2)?;port.work(2,size_of::<DeflateSnapshot>())?;frame.snapshot.compression_method=method;frame.snapshot.window_bits=window;frame.snapshot.compression_level_hint=DeflateLevelHint::from_bits(hint);frame.snapshot.dict_id=dictionary;port.vector(rows.len(),&mut frame.snapshot.payload,2)?;}
 for(position,index)in frame.ordered.iter().copied().enumerate(){port.work(2,size_of::<u8>())?;let row=&rows[index];if integer(row,2)?!=ordinal(position)?{return Err(invalid())}let value=bounded(row,3,255)?as u8;if let Some(source)=source{if source.payload[position]!=value{return Err(invalid())}}else{frame.snapshot.payload.push(value)}if(position+1)%256==0{port.control.checkpoint(port.phase(),position+1,rows.len())?}}port.control.checkpoint(port.phase(),rows.len(),rows.len())
}
pub struct Settlement<'a,'b>{control:RefCell<SqliteSnapshotReceivingControl<'a,'b>>,before:usize,remaining:usize,phase:SqliteSnapshotPhase,post_body:Cell<bool>,cause:RefCell<Option<ValueError>>}
impl<'a,'b> Settlement<'a,'b>{
 pub fn new(control:&'a mut SqliteSnapshotControl<'b>,before:usize,phase:SqliteSnapshotPhase)->Self{let remaining=control.allocation_remaining_bytes();Self{control:RefCell::new(control.receiving_scope()),before,remaining,phase,post_body:Cell::new(false),cause:RefCell::new(None)}}
 fn settle(&self,owned:usize)->Result<()>{settle(&mut self.control.borrow_mut(),self.remaining,self.before,owned)}
 pub fn finish_body(&self,owned:usize)->Result<()>{self.settle(owned)?;self.post_body.set(true);Ok(())}
 pub fn observe(&self,owned:usize,completed:usize,total:usize)->bool{if !self.post_body.get(){return true}match self.settle(owned).and_then(|_|self.control.borrow_mut().checkpoint(self.phase,completed,total)){Ok(())=>true,Err(error)=>{*self.cause.borrow_mut()=Some(error);false}}}
 fn refused(&self,owned:usize,error:ValueError)->ValueError{match self.settle(owned){Err(cause)=>cause,Ok(())=>self.cause.borrow_mut().take().unwrap_or(error)}}
}
macro_rules! receive{
 ($name:ident,$owner:ident,$progress:path,$direction:ident,$phase:ident,$output:ty,$operation:expr,$publish:expr)=>{
 pub(super)fn $name(source:Option<&DeflateSnapshot>,database:Option<&SqliteDatabase>,control:&mut SqliteSnapshotControl<'_>,owner:&mut $owner<'_,'_>)->Result<$output>{
  let result=(||{owner.native().checkpoint()?;let before=owner.native().owned_bytes();let maximum=add(before,control.allocation_remaining_bytes())?;let settlement=Settlement::new(control,before,SqliteSnapshotPhase::$phase);let mut observer=|event:$progress|settlement.observe(event.owned_bytes,event.completed,event.total);let result=owner.scoped_native(maximum,&mut observer,|owner|owner.receive::<Frame,$output>(|slot,native,body|{let mut control=settlement.control.borrow_mut();let mut port=Paid{control:&mut **control,native:Direction::$direction(native),body};port.work(1,size_of::<Frame>())?;*slot=Some(Frame::new());let frame=slot.as_mut().unwrap();port.work(1,size_of::<$output>())?;frame.status=Some(($operation)(source,database,frame,&mut port));let owned=port.owned();drop(port);drop(control);settlement.finish_body(owned)?;frame.status.take().unwrap()?;($publish)(frame)}));match result{Ok(output)=>Ok(output),Err(error)=>Err(settlement.refused(owner.native().owned_bytes(),error))}})();result.map_err(|error|error.with_retained_progress(owner.progress()))
 }
 };
}
receive!(project_receiving,NativeSnapshotDecodeOwner,semio_framework_value::native_decoding::NativeDecodeProgress,Decode,ProjectSnapshot,SqliteDatabase,|source:Option<&DeflateSnapshot>,_:Option<&SqliteDatabase>,frame:&mut Frame,port:&mut Paid<'_,'_,'_>|project(source.unwrap(),frame,port),|frame:&mut Frame|Ok(std::mem::replace(&mut frame.projection.database,SqliteDatabase{tables:Vec::new()})));
receive!(reconstruct_receiving,NativeSnapshotEncodeOwner,semio_framework_value::native_encoding::NativeEncodeProgress,Encode,ReconstructSnapshot,DeflateSnapshot,|_:Option<&DeflateSnapshot>,database:Option<&SqliteDatabase>,frame:&mut Frame,port:&mut Paid<'_,'_,'_>|read(database.unwrap(),frame,None,port),|frame:&mut Frame|Ok(std::mem::replace(&mut frame.snapshot,empty())));
receive!(validate_decoding,NativeSnapshotDecodeOwner,semio_framework_value::native_decoding::NativeDecodeProgress,Decode,ProjectSnapshot,(),|source:Option<&DeflateSnapshot>,database:Option<&SqliteDatabase>,frame:&mut Frame,port:&mut Paid<'_,'_,'_>|read(database.unwrap(),frame,source,port),|_:&mut Frame|Ok(()));
receive!(validate_encoding,NativeSnapshotEncodeOwner,semio_framework_value::native_encoding::NativeEncodeProgress,Encode,ReconstructSnapshot,(),|source:Option<&DeflateSnapshot>,database:Option<&SqliteDatabase>,frame:&mut Frame,port:&mut Paid<'_,'_,'_>|read(database.unwrap(),frame,source,port),|_:&mut Frame|Ok(()));
